import base64
import builtins
import io
import logging
import pickle

logger = logging.getLogger(__name__)


class SafeUnpickler(pickle.Unpickler):
    """Unpickler that only allows safe built-in types to prevent code injection."""
    # Allowed safe types that can appear in a preferences dictionary
    SAFE_TYPES = {
        "dict", "list", "tuple", "str", "int", "float", "bool",
        "type(None)"  # for NoneType, module='builtins' and name='NoneType'? Actually None is type(None).
    }

    def find_class(self, module, name):
        if module == "builtins" and name in self.SAFE_TYPES:
            # Handle NoneType special case: name is 'NoneType' but getattr(builtins, 'NoneType') works.
            return getattr(builtins, name)
        raise pickle.UnpicklingError(
            f"Unsafe class {module}.{name} found in pickle data"
        )


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    The cookie contains pickled preference settings (legacy format), encoded in Base64.
    This function safely decodes the string and deserializes the data, restricting
    allowed types to built-in Python objects in order to prevent remote code execution.

    Args:
        encoded_prefs: A base64-encoded string containing the user preferences.

    Returns:
        A dictionary of preference settings. Returns an empty dictionary if the
        input is blank, cannot be decoded, or does not represent a valid dict.
    """
    if not encoded_prefs:
        return {}

    try:
        decoded_bytes = base64.b64decode(encoded_prefs)
        # Use safe unpickler to avoid arbitrary code execution
        preferences = SafeUnpickler(io.BytesIO(decoded_bytes)).load()
        if not isinstance(preferences, dict):
            logger.warning("Decoded cookie is not a dict: %s", type(preferences))
            return {}
        return preferences
    except (base64.binascii.Error, pickle.UnpicklingError, Exception) as e:
        logger.warning("Failed to decode/parse preferences cookie: %s", e)
        return {}

