import json
import pickle
import builtins


class SafeUnpickler(pickle.Unpickler):
    """A restricted Unpickler that only allows safe built-in types."""
    def find_class(self, module, name):
        # Only allow builtins module
        if module == "builtins":
            # Whitelist safe types
            if name in {
                "dict", "list", "tuple", "str", "int", "float", "bool",
                "bytes", "set", "frozenset", "NoneType"
            }:
                return getattr(builtins, name)
        # Forbid everything else
        raise pickle.UnpicklingError(f"Attempted to load unsafe type {module}.{name}")


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Supports both legacy pickle-based cookies (via safe unpickling) and
    newer JSON-encoded cookies.

    Args:
        encoded_prefs: A base64-encoded string containing user preferences

    Returns:
        A dictionary containing the user's preference settings.
        Returns an empty dict if decoding or parsing fails.
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # First, try to safely unpickle the data (for legacy cookies).
        # Only basic built-in types are allowed, preventing code execution.
        try:
            preferences = SafeUnpickler(io.BytesIO(decoded_data)).load()
            if isinstance(preferences, dict):
                return preferences
        except (pickle.UnpicklingError, pickle.PickleError, TypeError, ValueError, AttributeError):
            # If safe pickle fails, fall through to try JSON
            pass

        # Try JSON decoding as a fallback or for newer cookies
        try:
            preferences = json.loads(decoded_data)
            if isinstance(preferences, dict):
                return preferences
        except (json.JSONDecodeError, UnicodeDecodeError):
            pass

        # If we reach here, the data could not be parsed into a dictionary
        return {}
    except (base64.binascii.Error, Exception):
        # Malformed base64 or unexpected errors
        return {}

