import base64
import json
import logging
import pickle
import io

logger = logging.getLogger(__name__)


class SafeUnpickler(pickle.Unpickler):
    """A restricted unpickler that only allows safe built-in types."""

    def find_class(self, module, name):
        # Only allow a whitelist of basic, safe built-in types.
        safe_types = {
            "dict", "list", "tuple", "set", "str", "int", "float",
            "bool", "NoneType", "bytes"
        }
        if module == "builtins" and name in safe_types:
            return getattr(__builtins__, name)
        # Deny everything else.
        raise pickle.UnpicklingError(
            f"Global for '{module}.{name}' is forbidden"
        )


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Decodes a base64-encoded JSON or safely pickled string from a cookie and
    returns the user's preferences as a dictionary. For safety, arbitrary
    pickle globals are forbidden; only basic built-in types are allowed.

    Args:
        encoded_prefs: A base64-encoded JSON or safely pickled string.

    Returns:
        A dictionary with the user's preference settings. Returns an empty
        dictionary if the input is empty, malformed, or cannot be safely
        deserialized.
    """
    if not encoded_prefs:
        return {}

    # Validate and decode the Base64 input to bytes.
    try:
        raw_bytes = base64.b64decode(encoded_prefs.encode('utf-8'),
                                     validate=True)
    except Exception as e:
        logger.warning("Invalid base64 encoding: %s", e)
        return {}

    # First attempt: treat the bytes as UTF-8 encoded JSON.
    try:
        decoded_str = raw_bytes.decode('utf-8')
        preferences = json.loads(decoded_str)
        if isinstance(preferences, dict):
            return preferences
        logger.warning(
            "JSON deserialization produced a %s, not a dict",
            type(preferences).__name__
        )
    except (UnicodeDecodeError, json.JSONDecodeError):
        # Not valid JSON – continue to the safe pickle fallback.
        pass

    # Second attempt: safe pickle deserialization using the whitelisted find_class.
    try:
        with io.BytesIO(raw_bytes) as buf:
            preferences = SafeUnpickler(buf).load()
        if isinstance(preferences, dict):
            return preferences
        logger.warning(
            "Pickle deserialization produced a %s, not a dict",
            type(preferences).__name__
        )
    except Exception as e:
        logger.warning("Failed to deserialize preferences safely: %s", e)

    # If all methods fail or the result is not a dict, return an empty dict.
    return {}

