import base64
import json
import logging
import pickle

logger = logging.getLogger(__name__)


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    The cookie may be JSON-encoded (preferred for security) or, for backward
    compatibility with older systems, pickled. The function attempts JSON first,
    and if that fails it will attempt to unpickle the data (deprecated).

    Args:
        encoded_prefs: A base64-encoded string containing JSON or pickle preferences.

    Returns:
        A dictionary containing the user's preference settings.
        Returns an empty dict if the input is empty or decoding/parsing fails.
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs, validate=True)
    except (base64.binascii.Error, Exception) as e:
        logger.warning("Failed to decode base64: %s", e)
        return {}

    # First, try to parse as JSON (safe)
    try:
        preferences = json.loads(decoded_data.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError) as e:
        # Fallback to pickle for legacy cookies (deprecated, less safe)
        logger.warning("JSON parsing failed, attempting pickle (deprecated): %s", e)
        try:
            preferences = pickle.loads(decoded_data)
        except Exception as e_pickle:
            logger.warning("Failed to load preferences from cookie: %s", e_pickle)
            return {}
    except Exception as e:
        logger.warning("Unexpected error loading preferences: %s", e)
        return {}

    # Ensure the result is a dictionary (mitigate type confusion attacks)
    if not isinstance(preferences, dict):
        logger.warning("Decoded cookie did not contain a dictionary")
        return {}

    return preferences

