import base64
import pickle
import builtins
import io


class SafeUnpickler(pickle.Unpickler):
    """
    A restricted unpickler that only allows safe built-in types.
    This prevents arbitrary code execution while still being able to
    deserialize basic data structures.
    """
    def find_class(self, module, name):
        # Only allow simple, safe built-in types
        if module == "builtins":
            safe_types = {
                "dict", "list", "str", "int", "float", "bool",
                "tuple", "bytes", "NoneType", "frozenset", "set"
            }
            if name in safe_types:
                return getattr(builtins, name)
        raise pickle.UnpicklingError(f"Forbidden class: {module}.{name}")


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing pickled user preferences

    Returns:
        A dictionary containing the user's preference settings
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # Safely unpickle the data, only allowing basic types
        preferences = SafeUnpickler(io.BytesIO(decoded_data)).load()

        # Ensure the result is a dictionary
        if not isinstance(preferences, dict):
            return {}
        return preferences
    except (ValueError, TypeError, pickle.UnpicklingError, pickle.PicklingError):
        return {}

